import app from 'flarum/forum/app';
import Icon from 'flarum/common/components/Icon';
/**
 * Builds the Blessing Skin glyph (or the uploaded image) as a vnode.
 *
 * This is a plain helper that returns a vnode, not a component: Flarum 2 runs
 * on Mithril 2, where a component function must return a `{ view }` closure
 * rather than a vnode, so `<BlessingIcon />` would crash during rendering.
 */
export default function blessingIcon(className = 'BlessingOAuth-icon') {
  const image = app.forum.attribute('blessing-oauth-client.loginIconImage');
  if (image) {
    return m("img", {
      className: `${className} BlessingOAuth-iconImage`,
      src: image,
      alt: ""
    });
  }
  return m(Icon, {
    name: app.forum.attribute('blessing-oauth-client.loginIcon') || 'far fa-id-card',
    className: className
  });
}
flarum.reg.add('tacraft-sociality-blessing-oauth', 'forum/components/BlessingIcon', blessingIcon);