import app from 'flarum/forum/app';
import Component from 'flarum/common/Component';
import FieldSet from 'flarum/common/components/FieldSet';
import Button from 'flarum/common/components/Button';
import LoadingIndicator from 'flarum/common/components/LoadingIndicator';
import humanTime from 'flarum/common/helpers/humanTime';
import extractText from 'flarum/common/utils/extractText';
import blessingIcon from './BlessingIcon';
const PREFIX = 'blessing-oauth-client.forum.link';
const LINK_PATH = '/blessing-oauth/callback';
const LINK_STATUS_ENDPOINT = '/blessing-oauth/link';
const ENABLED_ATTRIBUTE = 'blessing-oauth-client.enabled';
const PROVIDER_NAME_ATTRIBUTE = 'blessing-oauth-client.providerName';
/**
 * The provider name configured in the admin settings, e.g. "Blessing Skin".
 */
function providerName() {
  return app.forum.attribute(PROVIDER_NAME_ATTRIBUTE) || 'Blessing Skin';
}

/**
 * Translate a link-panel string with the configured provider name.
 */
function trans(key, params = {}) {
  return app.translator.trans(key, {
    provider: providerName(),
    ...params
  });
}

/**
 * Shows whether the current user has linked a provider account, and lets them
 * link or unlink one from their security settings.
 */
export default class BlessingLinkedAccount extends Component {
  state = {
    loading: true,
    failed: false,
    unlinking: false,
    status: null
  };
  oninit(vnode) {
    super.oninit(vnode);
    void this.load();
  }
  view() {
    return m(FieldSet, {
      className: "BlessingOAuth-linkedAccount",
      label: trans(`${PREFIX}.heading`)
    }, m("p", {
      className: "helpText"
    }, trans(`${PREFIX}.help`)), this.state.loading ? m(LoadingIndicator, null) : this.state.failed ? this.errorView() : this.accountView());
  }
  errorView() {
    return m("div", {
      className: "BlessingOAuth-Account-errors"
    }, m("p", {
      className: "helpText"
    }, trans(`${PREFIX}.load_failed`)), m(Button, {
      className: "Button",
      onclick: () => this.load()
    }, trans(`${PREFIX}.retry`)));
  }
  accountView() {
    const linked = this.state.status?.linked === true;
    return m("div", {
      className: `BlessingOAuth-Account ${linked ? 'BlessingOAuth-Account--linked' : 'BlessingOAuth-Account--unlinked'}`
    }, m("div", {
      className: "BlessingOAuth-Account-icon"
    }, blessingIcon('BlessingOAuth-icon BlessingOAuth-Account-logo')), m("div", {
      className: "BlessingOAuth-Account-info"
    }, m("span", {
      className: "BlessingOAuth-Account-name"
    }, trans(`${PREFIX}.name`)), m("span", {
      className: "BlessingOAuth-Account-status"
    }, trans(`${PREFIX}.${linked ? 'status_linked' : 'status_unlinked'}`)), linked ? this.linkedMeta() : null), m("div", {
      className: "BlessingOAuth-Account-actions"
    }, linked ? this.linkedActions() : this.unlinkedActions()));
  }
  linkedMeta() {
    const status = this.state.status;
    const identifier = status?.identifier;
    const createdAt = status?.createdAt;
    if (!identifier && !createdAt) {
      return null;
    }
    return m("span", {
      className: "BlessingOAuth-Account-meta"
    }, identifier ? trans(`${PREFIX}.identifier`, {
      identifier
    }) : null, identifier && createdAt ? ' · ' : null, createdAt ? trans(`${PREFIX}.linked_at`, {
      time: humanTime(new Date(createdAt))
    }) : null);
  }
  unlinkedActions() {
    return m(Button, {
      className: "Button BlessingOAuth-Account-bind",
      onclick: () => this.startLink()
    }, trans(`${PREFIX}.bind_button`));
  }
  linkedActions() {
    return [m(Button, {
      className: "Button",
      onclick: () => this.startLink(),
      disabled: this.state.unlinking
    }, trans(`${PREFIX}.rebind_button`)), m(Button, {
      className: "Button",
      onclick: () => this.unlink(),
      loading: this.state.unlinking
    }, trans(`${PREFIX}.unbind_button`))];
  }
  startLink() {
    const baseUrl = String(app.forum.attribute('baseUrl') ?? '').replace(/\/+$/, '');
    const returnTo = `${window.location.pathname}${window.location.search}`;
    window.location.href = `${baseUrl}${LINK_PATH}?link=1&returnTo=${encodeURIComponent(returnTo)}`;
  }
  async unlink() {
    if (!confirm(extractText(trans(`${PREFIX}.unlink_confirm`)))) {
      return;
    }
    this.state.unlinking = true;
    m.redraw();
    try {
      await app.request({
        method: 'DELETE',
        url: `${app.forum.attribute('apiUrl')}${LINK_STATUS_ENDPOINT}`
      });
      this.state.status = {
        linked: false,
        identifier: null,
        createdAt: null,
        lastLoginAt: null
      };
      app.alerts.show({
        type: 'success'
      }, trans(`${PREFIX}.unlinked_success`));
    } catch {
      app.alerts.show({
        type: 'error'
      }, trans(`${PREFIX}.unlink_failed`));
    } finally {
      this.state.unlinking = false;
      m.redraw();
    }
  }
  async load() {
    if (!app.forum.attribute(ENABLED_ATTRIBUTE)) {
      this.state.loading = false;
      this.state.failed = false;
      return;
    }
    this.state.loading = true;
    this.state.failed = false;
    m.redraw();
    try {
      this.state.status = await app.request({
        method: 'GET',
        url: `${app.forum.attribute('apiUrl')}${LINK_STATUS_ENDPOINT}`
      });
    } catch {
      this.state.failed = true;
    } finally {
      this.state.loading = false;
      m.redraw();
    }
  }
}
flarum.reg.add('tacraft-sociality-blessing-oauth', 'forum/components/BlessingLinkedAccount', BlessingLinkedAccount);